import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { Show, splitProps } from 'solid-js';
import styles from './List.module.css';

type ListMarker = 'disc' | 'decimal' | 'none';
type ListGap = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';
type ListSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type ListTone = 'default' | 'muted' | 'subtle' | 'primary' | 'destructive';

type ListBaseProps = {
  marker?: ListMarker;
  gap?: ListGap;
  size?: ListSize;
  tone?: ListTone;
};

type ListDataProps = {
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
};

type ListRootProps =
  | (HTMLArkProps<'ul'> &
      ListBaseProps &
      ListDataProps & {
        as?: 'ul';
        'data-gap'?: string;
        'data-marker'?: string;
        'data-size'?: string;
        'data-tone'?: string;
      })
  | (HTMLArkProps<'ol'> &
      ListBaseProps &
      ListDataProps & {
        as: 'ol';
        'data-gap'?: string;
        'data-marker'?: string;
        'data-size'?: string;
        'data-tone'?: string;
      });

function ListRoot(props: ListRootProps) {
  return (
    <Show
      when={props.as === 'ol'}
      fallback={<UnorderedListRoot {...(props as Extract<ListRootProps, { as?: 'ul' }>)} />}
    >
      <OrderedListRoot {...(props as Extract<ListRootProps, { as: 'ol' }>)} />
    </Show>
  );
}

function OrderedListRoot(props: Extract<ListRootProps, { as: 'ol' }>) {
  const [local, others] = splitProps(props, [
    'as',
    'asChild',
    'class',
    'gap',
    'marker',
    'role',
    'size',
    'tone',
    'data-scope',
    'data-part',
    'data-slot',
    'data-gap',
    'data-marker',
    'data-size',
    'data-tone',
  ]);

  return (
    <ark.ol
      asChild={local.asChild}
      {...others}
      role={local.role ?? (local.marker === 'none' ? 'list' : undefined)}
      data-scope="list"
      data-part="root"
      data-slot="list-root"
      data-gap={local.gap ?? 'sm'}
      data-marker={local.marker ?? 'auto'}
      data-size={local.size ?? 'md'}
      data-tone={local.tone ?? 'default'}
      class={clsx(styles.root, local.class)}
    />
  );
}

function UnorderedListRoot(props: Extract<ListRootProps, { as?: 'ul' }>) {
  const [local, others] = splitProps(props, [
    'as',
    'asChild',
    'class',
    'gap',
    'marker',
    'role',
    'size',
    'tone',
    'data-scope',
    'data-part',
    'data-slot',
    'data-gap',
    'data-marker',
    'data-size',
    'data-tone',
  ]);

  return (
    <ark.ul
      asChild={local.asChild}
      {...others}
      role={local.role ?? (local.marker === 'none' ? 'list' : undefined)}
      data-scope="list"
      data-part="root"
      data-slot="list-root"
      data-gap={local.gap ?? 'sm'}
      data-marker={local.marker ?? 'auto'}
      data-size={local.size ?? 'md'}
      data-tone={local.tone ?? 'default'}
      class={clsx(styles.root, local.class)}
    />
  );
}

function ListItem(props: HTMLArkProps<'li'> & ListDataProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-scope',
    'data-part',
    'data-slot',
  ]);

  return (
    <ark.li
      asChild={local.asChild}
      {...others}
      data-scope="list"
      data-part="item"
      data-slot="list-item"
      class={local.class}
    />
  );
}

const List = Object.assign(ListRoot, {
  Root: ListRoot,
  Item: ListItem,
});

export { List };

@layer moduix.components {
  .root[data-scope='list'][data-part='root'] {
    --_list-color: var(
      --moduix-list-color,
      var(--moduix-list-default-color, var(--moduix-color-foreground))
    );
    --_list-font-size: var(
      --moduix-list-font-size,
      var(--moduix-list-font-size-md, var(--moduix-text-md))
    );
    --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-sm, var(--moduix-spacing-2)));
    --_list-line-height: var(
      --moduix-list-line-height,
      var(--moduix-list-line-height-md, var(--moduix-line-height-text-md))
    );

    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--_list-gap);
    margin: 0;
    padding: 0;
    color: var(--_list-color);
    font-family: var(--moduix-list-font-family, inherit);
    font-size: var(--_list-font-size);
    font-weight: var(--moduix-list-font-weight, var(--moduix-weight-regular));
    line-height: var(--_list-line-height);
    letter-spacing: var(--moduix-list-letter-spacing, 0);
    list-style-position: outside;
    overflow-wrap: break-word;

    &[data-gap='xs'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-xs, var(--moduix-spacing-1)));
    }

    &[data-gap='sm'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-sm, var(--moduix-spacing-2)));
    }

    &[data-gap='md'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-md, var(--moduix-spacing-3)));
    }

    &[data-gap='lg'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-lg, var(--moduix-spacing-4)));
    }

    &[data-gap='xl'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-xl, var(--moduix-spacing-5)));
    }

    &[data-gap='2xl'] {
      --_list-gap: var(--moduix-list-gap, var(--moduix-list-gap-2xl, var(--moduix-spacing-6)));
    }

    & > li::marker {
      color: var(--moduix-list-marker-color, currentColor);
      font-weight: var(--moduix-list-marker-font-weight, inherit);
    }

    &[data-marker='none'] {
      padding-inline-start: 0;
      list-style: none;
    }

    &:is(ul, ol)[data-marker='auto'],
    &[data-marker='disc'],
    &[data-marker='decimal'] {
      padding-inline-start: var(--moduix-list-padding-x, var(--moduix-spacing-5));
    }

    &:is(ul)[data-marker='auto'],
    &[data-marker='disc'] {
      list-style-type: disc;
    }

    &:is(ol)[data-marker='auto'] {
      list-style-type: revert;
    }

    &:is(ul)[data-marker='decimal'],
    &:is(ol)[data-marker='decimal'] {
      list-style-type: decimal;
    }

    &[data-size='xs'] {
      --_list-font-size: var(
        --moduix-list-font-size,
        var(--moduix-list-font-size-xs, var(--moduix-text-xs))
      );
      --_list-line-height: var(
        --moduix-list-line-height,
        var(--moduix-list-line-height-xs, var(--moduix-line-height-text-xs))
      );
    }

    &[data-size='sm'] {
      --_list-font-size: var(
        --moduix-list-font-size,
        var(--moduix-list-font-size-sm, var(--moduix-text-sm))
      );
      --_list-line-height: var(
        --moduix-list-line-height,
        var(--moduix-list-line-height-sm, var(--moduix-line-height-text-sm))
      );
    }

    &[data-size='md'] {
      --_list-font-size: var(
        --moduix-list-font-size,
        var(--moduix-list-font-size-md, var(--moduix-text-md))
      );
      --_list-line-height: var(
        --moduix-list-line-height,
        var(--moduix-list-line-height-md, var(--moduix-line-height-text-md))
      );
    }

    &[data-size='lg'] {
      --_list-font-size: var(
        --moduix-list-font-size,
        var(--moduix-list-font-size-lg, var(--moduix-text-lg))
      );
      --_list-line-height: var(
        --moduix-list-line-height,
        var(--moduix-list-line-height-lg, var(--moduix-line-height-text-lg))
      );
    }

    &[data-size='xl'] {
      --_list-font-size: var(
        --moduix-list-font-size,
        var(--moduix-list-font-size-xl, var(--moduix-text-xl))
      );
      --_list-line-height: var(
        --moduix-list-line-height,
        var(--moduix-list-line-height-xl, var(--moduix-line-height-text-xl))
      );
    }

    &[data-tone='default'] {
      --_list-color: var(
        --moduix-list-color,
        var(--moduix-list-default-color, var(--moduix-color-foreground))
      );
    }

    &[data-tone='muted'] {
      --_list-color: var(
        --moduix-list-color,
        var(--moduix-list-muted-color, var(--moduix-color-muted-foreground))
      );
    }

    &[data-tone='subtle'] {
      --_list-color: var(
        --moduix-list-color,
        var(--moduix-list-subtle-color, var(--moduix-color-secondary-foreground))
      );
    }

    &[data-tone='primary'] {
      --_list-color: var(
        --moduix-list-color,
        var(--moduix-list-primary-color, var(--moduix-color-primary))
      );
    }

    &[data-tone='destructive'] {
      --_list-color: var(
        --moduix-list-color,
        var(--moduix-list-destructive-color, var(--moduix-color-destructive))
      );
    }
  }
}
